const tasks = [
["instructions", "for p in /AGENTS.md /user/AGENTS.md /user/user1/AGENTS.md /user/user1/harbor-runs/AGENTS.md /user/user1/harbor-runs/e16b811ebce7/AGENTS.md /workspace/AGENTS.md; do if [ -f \"$p\" ]; then printf '%s\\n' \"$p\"; cat \"$p\"; fi; done; find -L incident -name AGENTS.md -print"],
["scene", "cat incident/SCENE.json incident/INPUTS.json"],
["dataset case", "cat incident/dataset/CASE.json incident/dataset/PUBLIC_PROVENANCE.json"],
["configuration", "cat incident/run/effective_config.json"],
["catalog and manifest", "cat incident/dataset/catalog.json incident/dataset/manifest.json"],
["provenance selection", "cat incident/provenance/selection.json"],
["resume state", "cat incident/checkpoints/actor/latest_checkpointed_iteration.txt incident/checkpoints/actor/iter_0000003/metadata.json incident/checkpoints/actor/rollout/data_state_3.json incident/checkpoints/critic/latest_checkpointed_iteration.txt incident/checkpoints/critic/iter_0000003/metadata.json"]
];
const rs = await Promise.allSettled(tasks.map(([,cmd])=>tools.exec_command({cmd,workdir:"/workspace",yield_time_ms:10000,max_output_tokens:18000})));
rs.forEach((r,i)=>{text(tasks[i][0]); text(r.status==="fulfilled"?r.value.output:String(r.reason));});

